<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{$title}} · {{config('app.name')}}</title><style>body{font:13px/1.5 Arial,sans-serif;color:#1d2b40;margin:0;background:#f3f6fa}.sheet{max-width:900px;margin:28px auto;background:#fff;padding:42px;border:1px solid #e0e6ef}.top{display:flex;justify-content:space-between;border-bottom:2px solid #285fce;padding-bottom:18px;margin-bottom:24px}.brand{font-size:19px;font-weight:bold;color:#2459ba}.muted{color:#718098}.meta{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin:20px 0}.meta strong{display:block}table{width:100%;border-collapse:collapse;margin:18px 0}th{text-align:left;font-size:10px;text-transform:uppercase;color:#718098;letter-spacing:.5px}td,th{padding:10px;border-bottom:1px solid #e8edf4}td.num,th.num{text-align:right}.total{margin:16px 0 16px auto;width:290px}.total div{display:flex;justify-content:space-between;padding:5px}.grand{font-weight:bold;font-size:16px;border-top:2px solid #d8e1ee;padding-top:10px!important}.footer{margin-top:34px;padding-top:14px;border-top:1px solid #e7edf5;color:#718098;font-size:11px}.actions{max-width:900px;margin:18px auto;text-align:right}.btn{display:inline-block;padding:9px 14px;border-radius:7px;background:#285fce;color:#fff;text-decoration:none;border:0;cursor:pointer}@media print{body{background:#fff}.sheet{margin:0 auto;border:0;padding:12mm;max-width:none}.actions{display:none}@page{size:A4;margin:10mm}}</style></head><body><div class="actions"><button class="btn" onclick="window.print()">Print / Save as PDF</button></div><main class="sheet">@yield('content')<footer class="footer">{{DB::table('business_settings')->where('key','document_footer')->value('value') ?: 'Generated from recorded factory transactions.'}}</footer></main></body></html>
